insert into public.quote_model_sets (id, country_code, currency_code, version, taxes_included, tax_note, suggested_tax_percent, suggested_tax_label, suggested_tax_reference, methodology, sources, disclaimer, valid_from) values ('pt-2026-11', 'PT', 'EUR', '2026-11', false, 'Valores SEM IVA (somar 23% no continente).', 23, 'IVA 23% (continente)', 'Código do IVA, art. 18.º, n.º 1, alínea c)', 'Preços recomendados a partir das médias e intervalos publicados pelas principais plataformas de contratação de serviços em Portugal, tabelas de grandes prestadores e dados oficiais de custos, atualizados para 2026. Onde as fontes divergiam, foi usado o valor central para um profissional com seguro, fatura e garantia. Referências comerciais, não tabelas oficiais. Referência: Portugal continental.', array['Zaask – guias “Quanto custa” (zaask.pt/quanto-custa)', 'Habitissimo – guias de preços (habitissimo.pt/orcamentos)', 'Worten Resolve – preços tabelados de instalação elétrica e canalização', 'idealista/news – limpeza doméstica 2026 e custos de construção/mão de obra (INE)', 'INE / ECO – Índice de Custos de Construção de Habitação Nova 2025', 'ANECRA / DN – custo médio de mão de obra em oficinas (2026)', 'Casamentos.pt – catering de casamento por convidado', 'OCC / CRN Contabilidade – compensação por km em viatura própria'], 'Valores indicativos. Cada profissional deve validar com os seus custos reais (hora, seguro, combustível, margem) antes de publicar. Não constitui aconselhamento fiscal.', '2026-11-01');
