insert into public.quote_model_sets (id, country_code, currency_code, version, taxes_included, tax_note, suggested_tax_percent, suggested_tax_label, suggested_tax_reference, methodology, sources, disclaimer, valid_from) values ('br-2026-11', 'BR', 'BRL', '2026-11', true, 'Valor final ao cliente, impostos já inclusos.', null, null, null, 'Preços recomendados a partir de tabelas e guias de preço brasileiros publicados em 2026 (plataformas de contratação, portais de reforma baseados no SINAPI, tabelas de eletricistas, buffets, salões e clínicas). Onde as fontes divergiam, foi usado o valor central para um profissional formalizado (MEI/CNPJ), com nota fiscal e garantia, em capital do Sudeste. Referências comerciais, não tabelas oficiais.', array['SINAPI / Caixa e Lar Pontual (Portal da Reforma) – data-base 2026', 'Catraca Livre, Cidesp e Engenharia 360 – mão de obra de pedreiro 2026', 'Engehall e Lar Pontual – tabela de preços de eletricista 2026', 'Cronoshare e GetNinjas – encanador, diarista, design gráfico, fisioterapia, carreto e mudanças', 'Superprof, Labra e GetNinjas – hora-aula particular e reforço escolar', 'Casamentos.com.br, Plusdin e Freela Sem Crise – buffet, social media, tráfego pago, logotipo', 'Webmotors e Expert Zoom – pastilhas, discos e revisão', 'SICRO/DNIT (Orçamentor) – custo horário de trator com roçadeira (abr/2026)', 'Agilize, Meu Tudo e Booksy – psicólogo, nutricionista, manicure, depilação e sobrancelha'], 'Valores indicativos. Cada profissional deve validar com seus custos reais (hora, impostos, combustível, margem) antes de publicar. Não constitui orientação contábil ou fiscal.', '2026-11-01');
